def transform(grid):
    out=[r[:] for r in grid]
    # project 2 markers toward the 5 boundary to their right
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==2:
                out[r][c]=4
                for j in range(c+1,len(row)):
                    if grid[r][j]==5: break
                    out[r][j]=2
    # 5 boundary segment on left projects its color-coded rays inward
    for r,row in enumerate(grid):
        if row[0]==5:
            for c in range(1,len(row)):
                if grid[r][c]==5: break
                out[r][c]=2
    return out
